const {vec} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bunny.obj");

let pts = vertices.map(vertex => vec(...vertex));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};
pts = normalizeVectors(pts);

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const weight = (i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / 0.05);
const laplacian = graph.laplacian(weight);
const gradient = graph.gradient(weight);
const ids = Object.keys(graph.vertices);
const index = {};
ids.forEach((id, i) => { index[id] = i; });
const edges = [];
for (let i = 0; i < ids.length; i++) {
    for (const neighbor of graph.getNeighbors(ids[i])) {
        const j = index[neighbor];
        if (i < j) edges.push({i, j});
    }
}

// Graph Laplacian weights are ~1, so the time step is measured in graph hops (t ~ h^2 with h a few hops)
const baseTime = 4;
const identity = (() => {
    const builder = NMath.smat.builder(pts.length, pts.length);
    for (let i = 0; i < pts.length; i++) builder.set(i, i, 1);
    return builder.build();
})();

// One implicit Euler step: (I + t L) u = delta_source
const heatCache = new Map();
const implicitHeat = (source, time) => {
    const key = source + ":" + time;
    if (!heatCache.has(key)) {
        const t = baseTime * (1 + time / 10);
        const system = identity.add(laplacian.scale(t));
        const delta = vec.fromArray(pts.map((_, i) => (i === source ? 1 : 0)));
        heatCache.clear();
        heatCache.set(key, system.solve(delta, {maxIterations: 500, tolerance: 1e-8}));
    }
    return heatCache.get(key);
};

const localGradient = (vertexIndex, field) => {
    const neighbors = graph.getNeighbors(ids[vertexIndex]);
    if (neighbors.length === 0) return vec.zero(3);
    const systemData = [];
    const target = [];
    for (const neighbor of neighbors) {
        const neighborIndex = index[neighbor];
        const difference = pts[neighborIndex].sub(pts[vertexIndex]);
        systemData.push(...difference.toArray());
        target.push(field.components[neighborIndex] - field.components[vertexIndex]);
    }
    const localGradientVector = NMath.mat(systemData, [neighbors.length, 3]).solve(vec.fromArray(target));
    return localGradientVector.length() < 1e-12 ? vec.zero(3) : localGradientVector.normalize();
};

const reconstructDistance = (source, time) => {
    // log u keeps the local gradient fits scale-invariant (u decays exponentially away from the source)
    const heat = implicitHeat(source, time).map(x => Math.log(Math.max(x, 1e-300)));
    const gradients = pts.map((_, i) => localGradient(i, heat).scale(-1));
    const edgeGradient = edges.map(({i, j}) => {
        const direction = pts[j].sub(pts[i]);
        if (direction.length() === 0) return 0;
        return gradients[i].add(gradients[j]).scale(0.5).dot(direction.normalize());
    });
    const divergence = gradient.dot(vec.fromArray(edgeGradient));
    // L phi = div
    const rhs = divergence;
    const values = laplacian.solve(rhs, {maxIterations: 2000, tolerance: 1e-8}).toArray();
    const offset = values[source];
    return values.map(value => value - offset);
};

const neighborIdx = ids.map(id => graph.getNeighbors(id).map(neighbor => index[neighbor]));

// Deterministic RNG so the result is stable between slider changes
const makeRng = seed => () => {
    seed = (seed * 1664525 + 1013904223) % 4294967296;
    return seed / 4294967296;
};

const RANDOM_RESTART = false;

// Traces non-colliding paths of increasing distance; the end of each path is a cut locus candidate
const traceCutLocus = (d, source) => {
    const n = d.length;
    const rng = makeRng(12345);
    const visited = new Uint8Array(n);
    const candidates = new Uint8Array(n);
    const pathId = new Int32Array(n).fill(-1);
    let nextId = 0;
    const segments = [];
    visited[source] = 1;
    let unvisited = [];
    for (let i = 0; i < n; i++) if (!visited[i]) unvisited.push(i);
    let unvisitedCount = unvisited.length;
    const take = v => {
        visited[v] = 1;
        unvisitedCount--;
    };
    const step = v => {
        let best = -1;
        for (const u of neighborIdx[v]) {
            if (visited[u] || d[u] <= d[v]) continue;
            if (best < 0 || d[u] > d[best]) best = u;
        }
        return best;
    };
    // Advance all heads one step at a time so no path claims a large region
    const run = heads => {
        let active = heads;
        heads.forEach(v => { pathId[v] = nextId++; });
        while (active.length > 0) {
            const next = [];
            for (const v of active) {
                const u = step(v);
                if (u < 0) {
                    candidates[v] = 1;
                    // Higher vertices of other paths that blocked this one lie on the ridge where fronts meet
                    for (const w of neighborIdx[v]) {
                        if (w !== source && pathId[w] >= 0 && pathId[w] !== pathId[v] && d[w] > d[v]) candidates[w] = 1;
                    }
                } else {
                    take(u);
                    segments.push([v, u, pathId[v]]);
                    pathId[u] = pathId[v];
                    next.push(u);
                }
            }
            active = next;
        }
    };
    const starts = [];
    for (const v of neighborIdx[source]) {
        if (!visited[v]) {
            take(v);
            starts.push(v);
        }
    }
    run(starts);
    // Source neighbors exhausted: restart from random unvisited vertices until all are visited
    while (unvisitedCount > 0) {
        unvisited = unvisited.filter(v => !visited[v]);
        // Lowest-distance restarts give long paths that end only where fronts meet; random ones create noise
        const v = RANDOM_RESTART
            ? unvisited[Math.floor(rng() * unvisited.length)]
            : unvisited.reduce((best, u) => (d[u] < d[best] ? u : best), unvisited[0]);
        take(v);
        run([v]);
    }
    return {candidates, segments};
};

const GREEN = [0, 1, 0];
const GREY = [0.5, 0.5, 0.5];
const cutLocusColors = candidates => Array.from(candidates, flag => (flag ? GREEN : GREY));

const pathColor = id => {
    const hue = (id * 0.618034) % 1;
    const channel = offset => 0.5 + 0.5 * Math.cos(2 * Math.PI * (hue + offset));
    return [channel(0), channel(1 / 3), channel(2 / 3)];
};
const pathLines = segments => ({
    lines: segments.map(([a, b]) => [points[a], points[b]]),
    colors: segments.map(([, , id]) => pathColor(id)),
});


const points = pts.map(point => point.toArray());
const triangles = faces.map(({vertices: indices}) => indices.map(index => points[index]));
const triangleColors = colors => faces.map(({vertices: indices}) => indices.map(vertexIndex => colors[vertexIndex]));

let source = 0;
let time = 50;
const initialTrace = traceCutLocus(reconstructDistance(source, time), source);
const initialColors = cutLocusColors(initialTrace.candidates);
const initialPaths = pathLines(initialTrace.segments);
const pointPlot = IO.plotPointCloud(points, {color: initialColors});
const trianglePlot = IO.plotTriangleCloud(triangles, {color: triangleColors(initialColors)});
const pathPlot = IO.plotLineCloud(initialPaths.lines, {color: initialPaths.colors});

const updateGeodesic = () => {
    const trace = traceCutLocus(reconstructDistance(source, time), source);
    const colors = cutLocusColors(trace.candidates);
    const paths = pathLines(trace.segments);
    pointPlot.update(points, {color: colors});
    trianglePlot.update(triangles, {color: triangleColors(colors)});
    pathPlot.update(paths.lines, {color: paths.colors});
    pointPlot.render();
    pathPlot.render();
    trianglePlot.render();
};

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => trianglePlot},
        {type: "canvas", value: () => pathPlot},
    ]},
    {type: "slider", value: () => ({
        min: 0,
        max: 100,
        step: 1,
        value: 50,
        title: "Time step scale (t = 4(1 + s/10)):",
        onChange: value => { time = Number(value); updateGeodesic(); },
    })},
    {type: "slider", value: () => ({
        min: 0,
        max: pts.length - 1,
        step: 1,
        value: 0,
        title: "Heat source vertex:",
        onChange: value => { source = Math.round(value); updateGeodesic(); },
    })},
);
ui;
